//! 光标位图解码。
//!
//! ## 为什么光标要自己画
//!
//! RDP 服务端把光标形状当作**独立的更新消息**发过来（`Pointer Color Update`
//! / `Pointer Large Update` 等），并不保证把它合成进画面帧。实测：
//! 把指针移到新位置后，服务端一帧新画面都不发，画面里也找不到任何光标。
//!
//! FreeRDP 3.x 把这批消息的原始数据交给客户端（`rdp_pointer_update` 的六个
//! 回调），**绘制是客户端的事**——`xfreerdp` 有窗口可画，我们没有，
//! 所以要自己解码成位图、再由界面按桌面坐标贴上去。
//!
//! 位图格式有四种（`xorBpp` 决定），行尾还有对齐填充，踩错就是整张图花掉：
//!
//! | `xorBpp` | 格式 | 行对齐 | 行序 |
//! | --- | --- | --- | --- |
//! | 1 | AND/XOR 双掩码：XOR 位为 1 显白、为 0 显黑；AND 位为 1 **透明** | 2 字节 | 自上而下 |
//! | 16 | RGB565 | 2 字节 | **自下而上** |
//! | 24 | BGR888 | 2 字节 | **自下而上** |
//! | 32 | BGRA（含 alpha） | 2 字节 | **自下而上** |
//!
//! **行序这一列是本文件最容易踩的坑**：规范里两类掩码方向相反
//! （MS-RDPBCGR 2.2.9.1.1.4.4 / 2.2.9.1.1.3.2.1），FreeRDP 也把它写死成
//! `vFlip = (xorBpp != 1)`（`libfreerdp/codec/color.c`）。
//! 统一按自上而下读彩色光标，画出来的箭头就是**上下颠倒**的——
//! 形状还在、颜色也对，只是指着反方向，很容易被误判成"坐标算错了"。

/// 一张已解码的光标位图（紧凑 RGBA，内存序 `R,G,B,A`）。
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CursorSprite {
	/// 宽（像素）。
	pub width: u16,
	/// 高（像素）。
	pub height: u16,
	/// 热点 x——指针位置对应位图里的哪个像素。
	pub hot_x: u16,
	/// 热点 y。
	pub hot_y: u16,
	/// `width * height * 4` 字节的 RGBA。
	pub pixels: Vec<u8>,
}

/// 解码用的原始位图数据（对应 FreeRDP 的 `POINTER_COLOR_UPDATE`）。
#[derive(Debug, Clone, Copy)]
pub struct CursorBitmap<'a> {
	/// 宽（像素）。
	pub width: u16,
	/// 高（像素）。
	pub height: u16,
	/// 热点 x。
	pub hot_x: u16,
	/// 热点 y。
	pub hot_y: u16,
	/// XOR（颜色）掩码。
	pub xor_mask: &'a [u8],
	/// AND（透明）掩码。低分辨率光标必有；高分辨率光标可能为空。
	pub and_mask: &'a [u8],
}

/// 一行占多少字节。
///
/// **行尾填充是这类解码最容易错的地方**——按 `width * bpp / 8` 直接算，
/// 宽度稍大一点的位图就会整体错位、画出一团乱码。
///
/// 规范里两种掩码都只补到 **2 字节**边界（不是 4 字节）。24bpp 配奇数宽度时
/// 这两者结果不同：补 4 会把行首多推 2 字节，整张图错开。
pub const fn row_bytes(width: u16, bpp: u16) -> usize {
	let bytes = (width as usize * bpp as usize).div_ceil(8);
	(bytes + 1) & !1
}

/// 掩码里的第 `y` 行对应位图的第几行。
///
/// **彩色光标（`xorBpp != 1`）的掩码是自下而上的**，直接按 `y` 读会得到一张
/// 上下颠倒的图。规范见 MS-RDPBCGR 2.2.9.1.1.4.4（Color Pointer Update）
/// 里那句"bottom-up … scan-line data"，FreeRDP 的 `vFlip = (xorBpp != 1)`
/// 把它写死了。我们统一输出自上而下的位图，所以要在这里翻回来。
///
/// **实测确认**（192.168.10.20 真机抓的 32×32 箭头，掩码见
/// `docs/CURSOR-EVIDENCE.md`）：不翻的话箭头尖端落在左下、尾巴在右上，
/// 翻过来才是正常的「尖端左上、尾巴右下」。
const fn mask_row(y: usize, height: usize, bpp: u16) -> usize {
	if bpp == 1 { y } else { height - 1 - y }
}

/// 解码任意 `bpp` 的光标位图。`bpp` 只接受 1 / 16 / 24 / 32。
pub fn decode(bitmap: &CursorBitmap<'_>, bpp: u16) -> Option<CursorSprite> {
	let (width, height) = (bitmap.width, bitmap.height);
	if width == 0 || height == 0 {
		return None;
	}
	// 位图大到离谱时直接拒绝：脏数据不该让我们分配几百 MB
	let count = u32::from(width) * u32::from(height);
	if count > 16 * 1024 * 1024 {
		return None;
	}

	let mut pixels = vec![0u8; count as usize * 4];
	let stride = row_bytes(width, bpp);

	match bpp {
		1 => decode_1bpp(bitmap, stride, &mut pixels),
		16 => decode_bpp(bitmap, 16, stride, &mut pixels, rgb565),
		24 => decode_bpp(bitmap, 24, stride, &mut pixels, |src| {
			// BGR888
			[src[2], src[1], src[0], 255]
		}),
		32 => decode_bpp(bitmap, 32, stride, &mut pixels, |src| {
			// BGRA：alpha 在第 0 字节（内存序）
			[src[2], src[1], src[0], src[3]]
		}),
		_ => return None,
	}

	Some(CursorSprite {
		width,
		height,
		hot_x: bitmap.hot_x,
		hot_y: bitmap.hot_y,
		pixels,
	})
}

/// 解码 1bpp 的 AND/XOR 双掩码（RDP 5.0 的经典光标）。
///
/// 两个掩码各有 1 位，合起来是**四种**组合（出处 MS-RDPBCGR
/// "Drawing Monochrome Pointers"，FreeRDP 同样按四档处理）：
///
/// | AND | XOR | 含义 |
/// | --- | --- | --- |
/// | 0 | 0 | 黑 |
/// | 0 | 1 | 白 |
/// | 1 | 0 | 透明（背景透出来） |
/// | 1 | 1 | **反色**——按 `(x+y)&1` 黑白交替的棋盘格 |
///
/// **漏掉第四档的后果很隐蔽**：工字形（文本）光标整个就是用「反色」画的
/// ——真机抓的 32×32 工字形，1024 个像素里 998 个是「透明」、26 个是「反色」，
/// 一个黑白都没有。把 `AND=1` 一律当透明，那 26 个像素就被清成全透明，
/// **光标彻底看不见**（不是变暗、不是变花，是什么都没有）。
/// 反色的用意正是让光标在任何背景色上都看得出来。
fn decode_1bpp(bitmap: &CursorBitmap<'_>, stride: usize, pixels: &mut [u8]) {
	let width = bitmap.width as usize;
	let height = bitmap.height as usize;
	for y in 0..height {
		let row = mask_row(y, height, 1) * stride;
		for x in 0..width {
			let and_bit = bit_at(bitmap.and_mask, row, x);
			let xor_bit = bit_at(bitmap.xor_mask, row, x);
			// AND=1 时套用与彩色路径同一套规则（`apply_and_bit`）。
			// **要把该像素本来的颜色传进去**：规则是按颜色分档的
			// （黑→透明、白→反色），1bpp 里 XOR=1 显白、XOR=0 显黑。
			// 两条路径共用一个函数，免得「补了 24bpp 忘了 1bpp」这类漏洞。
			let base = if xor_bit == 1 {
				[255, 255, 255, 255]
			} else {
				[0, 0, 0, 255]
			};
			let rgba = if and_bit == 1 {
				apply_and_bit(1, base, x, y)
			} else {
				base
			};
			let offset = (y * width + x) * 4;
			pixels[offset..offset + 4].copy_from_slice(&rgba);
		}
	}
}

/// 解码 16/24/32 bpp 的 XOR 位图。
///
/// **两张掩码的行对齐基准不同**：XOR 按 `bpp` 算，AND 永远是 1bpp。
/// 混用会把每一行都读偏，整张图花掉。
///
/// 两者都**自下而上**存放，行号要先过 [`mask_row`] 翻回来。
///
/// **32bpp 的 AND 位不能一律当透明**：32bpp 掩码自带 alpha 通道，
/// 而抗锯齿边缘那些「AND=1」的像素带着半透明 alpha（实测真机数据里
/// 有 alpha 104/108 的边缘像素）。一律清成透明会让光标边缘变硬、
/// 露出锯齿。FreeRDP 的规则是（`libfreerdp/codec/color.c`）：AND=1 时
/// **只有纯黑才转透明**，其余保留掩码自带的 alpha。见 [`and_forces_transparent`]。
fn decode_bpp(
	bitmap: &CursorBitmap<'_>,
	or_bpp: u16,
	xor_stride: usize,
	pixels: &mut [u8],
	decode_pixel: impl Fn(&[u8]) -> [u8; 4],
) {
	let width = bitmap.width as usize;
	let height = bitmap.height as usize;
	let and_stride = row_bytes(bitmap.width, 1);
	let per_pixel = bytes_per_pixel(or_bpp);

	for y in 0..height {
		let src_y = mask_row(y, height, or_bpp);
		for x in 0..width {
			let offset = (y * width + x) * 4;
			let start = src_y * xor_stride + x * per_pixel;
			// 数据不足就少画几个像素，绝不越界
			let Some(src) = bitmap.xor_mask.get(start..start + per_pixel) else {
				continue;
			};
			let rgba = decode_pixel(src);
			let and_bit = bit_at(bitmap.and_mask, src_y * and_stride, x);
			let rgba = if and_bit == 1 {
				apply_and_bit(or_bpp, rgba, x, y)
			} else {
				rgba
			};
			pixels[offset..offset + 4].copy_from_slice(&rgba);
		}
	}
}

/// AND 位为 1 时给像素套用的规则（出处 `libfreerdp/codec/color.c`）。
///
/// **32bpp 分三档**（FreeRDP 原样）：纯黑转透明、纯白转反色、其余保留
/// 掩码自带的 alpha。中间那档「保留 alpha」是抗锯齿边缘的柔化过渡，
/// 清零会让光标轮廓变硬、露出锯齿。
///
/// **24bpp 只有两档**（同上，`else` 分支）：非黑即反色。它没有 alpha 通道，
/// 反色棋盘是唯一的手段——这正是 24bpp 的工字形光标能看见的原因。
/// 真机上 24bpp 工字形的像素构成与 1bpp 一致：绝大多数「透明」+ 少量「反色」。
fn apply_and_bit(or_bpp: u16, rgba: [u8; 4], x: usize, y: usize) -> [u8; 4] {
	match or_bpp {
		// 32bpp 三档。**判据是整个像素值**（FreeRDP 比的是 32 位 ARGB：
		// `0xFF000000` 不透明黑、`0xFFFFFFFF` 不透明白），不是只看 RGB——
		// 半透明的边缘像素必须原样放行，那是抗锯齿的柔化过渡。
		32 => match rgba {
			[0, 0, 0, 255] => [0, 0, 0, 0],
			[255, 255, 255, 255] => inverted_checkerboard(x, y),
			other => other,
		},
		// 24bpp 两档：非黑即反色。它没有 alpha 通道可用，
		// 反色棋盘是 24bpp 工字形唯一的可见手段。
		_ => {
			if rgba[0] == 0 && rgba[1] == 0 && rgba[2] == 0 {
				[0, 0, 0, 0]
			} else {
				inverted_checkerboard(x, y)
			}
		},
	}
}

/// 反色棋盘格：按 `(x+y)&1` 黑白交替。
///
/// 这样画出来的光标在**任意背景色**上都看得见——纯黑光标落在黑背景上
/// 就消失了，工字形尤其依赖这个。
fn inverted_checkerboard(x: usize, y: usize) -> [u8; 4] {
	let value = if (x + y).is_multiple_of(2) { 255 } else { 0 };
	[value, value, value, 255]
}

/// 每像素字节数，由位深直接决定——不能从数据长度反推。
const fn bytes_per_pixel(or_bpp: u16) -> usize {
	match or_bpp {
		16 => 2,
		24 => 3,
		32 => 4,
		_ => 1,
	}
}

/// 取位图里第 `x` 个像素的掩码位。
///
/// `row_start` 是**该行在掩码里的字节偏移**——行尾有对齐填充，
/// 在函数内部按位宽反推行长必然算错，所以交给调用方给。
/// 数据不足时返回 0（相当于不透明、不上色），宁可少画也不越界。
fn bit_at(data: &[u8], row_start: usize, x: usize) -> u8 {
	data.get(row_start + x / 8)
		.map_or(0, |byte| (byte >> (7 - (x % 8))) & 1)
}

/// RGB565 → RGBA。
fn rgb565(src: &[u8]) -> [u8; 4] {
	let value = u16::from(src[0]) | (u16::from(src[1]) << 8);
	let r = ((value >> 11) & 0x1F) as u8;
	let g = ((value >> 5) & 0x3F) as u8;
	let b = (value & 0x1F) as u8;
	// 5/6 位要拉到 8 位：位复制而不是乘常数，255 才能精确到白
	[
		(r << 3) | (r >> 2),
		(g << 2) | (g >> 4),
		(b << 3) | (b >> 2),
		255,
	]
}

